@Component
struct JobListItem {
  private itIndex: number = 0
  private jobData: JobData
  @Link currentSelectId: string
  @Prop workStatus: number
  @State isFold: boolean = false
  build() {
    Column() {
      Row () {
        Radio({ value: 'Radio'+(this.itIndex + 1), group: 'radioGroup' })
          .checked(this.jobData.id == this.currentSelectId)
          .height(20)
          .width(20)
          .enabled(this.workStatus == 0)
          .onChange((isChecked: boolean) => {
            console.log('this.currentSelectId:' + this.currentSelectId)
            if (isChecked) {
              this.currentSelectId = this.jobData.id
              AppStorage.Set<JobData>('jobModel', this.jobData)
            }
            console.log('Radio1 status is ' + isChecked)
          })

        Text(this.jobData.name).fontSize(16).fontWeight(500)

        Blank()
        Image($r("app.media.copy"))
          .width(24).height(24)
          .margin({right: 8})
          .onClick(() => {
            router.push({
              url: 'pages/editModel',
              params: {'jobData': this.jobData}
            })
          })

        Image($r("app.media.arrow_right"))
          .width(16).height(16)
          .rotate({x: 0, y: 0, z: 1, angle: this.isFold ? 0 : 90, centerX: '50%', centerY: '50%'})
          .onClick(() => {
            // Todo: 有什么办法能实现对某一下条目(模式)单独展开发收起？？？
            this.isFold = !this.isFold
            //                      if (this.isUnfold(item.id)) {
            //                         this.addUnfold(item.id)
            //                      } else {
            //                        this.removeUnfold(item.id)
            //                      }
          })
      }.width('100%').padding({left: 8, right: 8})

      Column({space:8}){
        ForEach(this.jobData.steps, (funcStep) => {
          Row({space:16}) {
            Text(funcStep.power + "W")
              .textAlign(TextAlign.Center)
              .textOverflow({ overflow: TextOverflow.None })
              .fontSize(16).fontWeight(400)

            Text(funcStep.minute + "分钟")
              .textAlign(TextAlign.Center)
              .fontSize(16).fontWeight(400)
          }
          .height(24)
        })

//        Row({space:16}) {
//          Text("200W")
//            .textAlign(TextAlign.Center)
//            .textOverflow({ overflow: TextOverflow.None })
//            .fontSize(16).fontWeight(400)
//
//          Text("10分钟")
//            .textAlign(TextAlign.Center)
//            .fontSize(16).fontWeight(400)
//        }.height(24)
      }
      .alignItems(HorizontalAlign.Start)
      .margin({left:28, right: 8})
      .visibility(this.isFold ? Visibility.Visible : Visibility.None)
    }
    .alignItems(HorizontalAlign.Start)
    .width('100%')
    .backgroundColor(this.itIndex % 2 ? '#f5f5f5' : '#e5e5e5')
  }
}
